//! Raw FFI bindings for libibverbs and mlx5dv, generated by bindgen from
//! rdma-core's `infiniband/verbs.h` and `infiniband/mlx5dv.h`.
//!
//! Everything named `ibv_*`, `mlx5dv_*` and `mlx5_*`, and the `IBV_*`,
//! `MLX5DV_*` and `MLX5_*` constants, is here as C declares it. Many verbs are
//! `static inline` in the headers (`ibv_post_send`, `ibv_poll_cq`,
//! `ibv_create_qp_ex`, `ibv_wr_*`, `ibv_start_poll`, ...); bindgen wraps them in
//! C functions compiled into this crate, so they are callable under their own
//! names, at the cost of one extra call. Code on the hot path can instead call
//! through the function pointers they read (`ibv_qp_ex::wr_send`,
//! `ibv_cq_ex::next_poll`, `ibv_context::ops`, ...).
//!
//! A verb the header redefines as a function-like macro keeps the name of the
//! function the macro expands to: `___ibv_query_port` is what C calls for
//! `ibv_query_port`, and `__ibv_reg_mr` for `ibv_reg_mr`. The plain names are
//! the library's own exported symbols (older entry points kept for
//! compatibility), which work too.
//!
//! With the `vendored` feature (the default) rdma-core is built from the
//! pinned submodule and this crate's tests and examples find it by their run
//! path; a dependent crate's binaries add `DEP_RDMA_CORE_LIB_DIR` to theirs.
//! Without it, the system's libibverbs and libmlx5 are linked. See
//! `docs/dev-setup.md` in the repository.
//!
//! The build script derives from rust-ibverbs's `ibverbs-sys` by Jon Gjengset,
//! Jonathan Behrens and contributors (MIT OR Apache-2.0).

#![no_std]
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(clippy::all)]
#![allow(rustdoc::all)]
#![allow(unsafe_op_in_unsafe_fn)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// The control segment that starts every mlx5 send WQE.
///
/// C declares it `__packed__` and `__aligned__(4)`, which Rust cannot say in
/// one type (bindgen's `packed(4)` would move `dci_stream_channel_id` from
/// offset 9 to 10), so the unaligned big-endian 16-bit field is a byte pair.
#[repr(C, align(4))]
#[derive(Debug, Default, Copy, Clone)]
pub struct mlx5_wqe_ctrl_seg {
    pub opmod_idx_opcode: __be32,
    pub qpn_ds: __be32,
    pub signature: u8,
    /// `__be16` in C, unaligned.
    pub dci_stream_channel_id: [u8; 2],
    pub fm_ce_se: u8,
    pub imm: __be32,
}

const _: () = {
    assert!(core::mem::size_of::<mlx5_wqe_ctrl_seg>() == 16);
    assert!(core::mem::align_of::<mlx5_wqe_ctrl_seg>() == 4);
    assert!(core::mem::offset_of!(mlx5_wqe_ctrl_seg, dci_stream_channel_id) == 9);
    assert!(core::mem::offset_of!(mlx5_wqe_ctrl_seg, fm_ce_se) == 11);
    assert!(core::mem::offset_of!(mlx5_wqe_ctrl_seg, imm) == 12);
};
